 4	/**
 5	 * Shared reproduction helpers for animal reproduction strategies.
 6	 */
 7	public abstract class AbstractReproductionStrategy implements ReproductionStrategy
 8	{
 9	    protected static final Random rand = Randomizer.getRandom();
10	
11	    protected boolean isBreedingAge(Animal animal)
12	    {
13	        return animal.getAge() >= animal.getBreedingAge();
14	    }
15	
16	    protected int generateBirthCount(Animal animal)
17	    {
18	        if(rand.nextDouble() <= animal.getBreedingProbability()) {
19	            return rand.nextInt(animal.getMaxLitterSize()) + 1;
20	        }
21	        return 0;
22	    }
23	
24	    protected void addOffspring(Animal animal, List<Actor> newAnimals, int births)
25	    {
26	        Field field = animal.getField();
27	        List<Location> free = field.getFreeAdjacentLocations(animal.getLocation());
28	        for(int b = 0; b < births && free.size() > 0; b++) {
29	            Location loc = free.remove(0);
30	            Animal.Gender sex = Randomizer.getRandomSex();
31	            Animal offspring = animal.createOffspring(field, loc, sex);
32	            offspring.setMovementStrategy(animal.getMovementStrategy());
33	            offspring.setReproductionStrategy(animal.getReproductionStrategy());
34	            newAnimals.add(offspring);
35	        }
36	    }
37	}
