 5	 */
 6	public class StandardSexualReproductionStrategy extends AbstractReproductionStrategy
 7	{
 8	    @Override
 9	    public void reproduce(Animal animal, List<Actor> newAnimals, Environment environment)
10	    {
11	        List<Organism> potentialMates = animal.getPotentialMates();
12	        if(!isBreedingAge(animal) || potentialMates.isEmpty()) {
13	            return;
14	        }
15	
16	        int births = generateBirthCount(animal);
17	        if(births == 0) {
18	            return;
19	        }
20	
21	        Animal mate = (Animal) potentialMates.get(rand.nextInt(potentialMates.size()));
22	        if(mate.isDiseased() && mate.getDisease().getDiseaseType() == DiseaseType.SEXUAL) {
23	            animal.setDisease(mate.getDisease());
24	        }
25	        addOffspring(animal, newAnimals, births);
26	    }
27	}
